package com.smarthub.plus;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class BroadcastEpgTest {
 @Test public void placeholdersDoNotBecomeMovieTitles(){assertFalse(ProgrammeTitle.available(" No Information "));assertFalse(ProgrammeTitle.available("لا يوجد دليل البرامج"));assertFalse(ProgrammeTitle.available("No EPG"));assertTrue(ProgrammeTitle.available("Unknown"));assertTrue(ProgrammeTitle.available("The Hangover"));}
 @Test public void nativeTimesAreUtcAndRejectImpossibleDates(){assertEquals(3600000,NativeEpgEvents.time("2026:11:02/03:00:00")-NativeEpgEvents.time("2026:11:02/02:00:00"));assertEquals(0,NativeEpgEvents.time("2026:02:30/02:00:00"));}
 @Test public void nativePacketsRequireTheRequestedProgramme()throws Exception{String packet="EPG_TDT\n0011\nSUCCESS:"+new JSONObject().put("prog_id",101).put("title","Film").put("start","2026:11:02/02:00:00").put("end","2026:11:02/04:00:00");assertEquals(1,NativeEpgEvents.packet(packet,101).size());assertTrue(NativeEpgEvents.packet(packet,102).isEmpty());assertTrue(NativeEpgEvents.packet(packet.replace("Film","No Information"),101).isEmpty());}
 private List<NativeEpgEvents.Event> parse(String xml)throws Exception{return StreamingXmlTv.read(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),"MBC 2 HD",NativeEpgEvents.time("2026:11:02/02:30:00"));}
 @Test public void currentAndUpcomingUseExactChannelAndTimezone()throws Exception{String xml="<tv><channel id='one'><display-name>MBC 2</display-name></channel><channel id='other'><display-name>MBC Masr 2</display-name></channel><programme channel='other' start='20261102050000 +0300' stop='20261102070000 +0300'><title>Wrong channel</title></programme><programme channel='one' start='20261102050000 +0300' stop='20261102070000 +0300'><title>Current film</title></programme><programme channel='one' start='20261102070000 +0300' stop='20261102090000 +0300'><title>Next film</title></programme></tv>";List<NativeEpgEvents.Event> events=parse(xml);assertEquals(2,events.size());long now=NativeEpgEvents.time("2026:11:02/02:30:00");assertEquals("Current film",BroadcastEpgProvider.current(events,now).title);assertEquals("Next film",BroadcastEpgProvider.next(events,now).title);}
 @Test public void ambiguousChannelNamesAreRejected()throws Exception{String xml="<tv><channel id='a'><display-name>MBC 2</display-name></channel><channel id='b'><display-name>MBC 2 HD</display-name></channel><programme channel='a' start='20261102000000 +0000' stop='20261102040000 +0000'><title>Film</title></programme></tv>";assertTrue(parse(xml).isEmpty());}
 @Test public void xmlExternalEntitiesAndDoctypesAreRejected(){try{parse("<!DOCTYPE tv [<!ENTITY x SYSTEM 'file:///private'>]><tv><channel id='one'><display-name>&x;</display-name></channel></tv>");fail("DTD accepted");}catch(Exception expected){}}
 @Test public void unrelatedNamesDoNotCauseGuideDownloads(){assertEquals("AE1",OnlineEpgGuide.feed("MBC 2 HD"));assertEquals("",OnlineEpgGuide.feed("Unmapped channel"));assertNotEquals(StreamingXmlTv.channelKey("MBC 2"),StreamingXmlTv.channelKey("MBC Masr 2"));}

 @org.junit.Test public void dtdSplitAcrossTinyReadsIsRejected(){byte[] xml="<!DOCTYPE tv [<!ENTITY x 'bad'>]><tv/>".getBytes(java.nio.charset.StandardCharsets.UTF_8);java.io.InputStream input=new java.io.ByteArrayInputStream(xml){public synchronized int read(byte[] bytes,int off,int length){return super.read(bytes,off,Math.min(length,3));}};org.junit.Assert.assertThrows(Exception.class,()->StreamingXmlTv.read(input,"MBC 2",System.currentTimeMillis()));}
 @org.junit.Test public void cancelledGuideStopsBeforeProcessing(){try{Thread.currentThread().interrupt();org.junit.Assert.assertThrows(Exception.class,()->StreamingXmlTv.read(new java.io.ByteArrayInputStream("<tv/>".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"MBC 2",System.currentTimeMillis()));}finally{Thread.interrupted();}}
}
